export function getAppCatalogEntry(serviceName: string): AppCatalogEntry | undefined {
  if (!serviceName) return undefined
  const clean = serviceName.toLowerCase().trim()
  return APP_CATALOG.find((app) => app.id.toLowerCase() === clean)
}

export function searchAppCatalog(query: string, category?: string): AppCatalogEntry[] {
  const q = (query || '').toLowerCase().trim()
  return APP_CATALOG.filter((app) => {
    if (category && category !== 'all') {
      if (category === 'native' && !app.isNative) return false
      if (category !== 'native' && app.category !== category) return false
    }
    if (!q) return true
    return (
      app.friendlyName.toLowerCase().includes(q) ||
      app.id.toLowerCase().includes(q) ||
      app.purpose.toLowerCase().includes(q) ||
      app.howItWorks.toLowerCase().includes(q) ||
      app.realWorldExample.toLowerCase().includes(q) ||
      String(app.port).includes(q)
    )
  })
}
